   if(!(await q.query("SELECT to_regclass('public.claus_prototype_intake') AS intake")).rows[0]?.intake)return true;
   const row=(await q.query('SELECT proposal FROM claus_prototype_intake WHERE project_id=$1',[p.id])).rows[0];
